INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('han-warring','韩','["韩","韩国"]',NULL,'{"periods":[{"rank":"侯","start":{"year":-403,"month":1,"confidence":"year"},"end":{"year":-324,"month":12,"confidence":"year"}},{"rank":"王","start":{"year":-323,"month":1,"confidence":"year"},"end":{"year":-230,"month":12,"confidence":"month"}}]}','cn','east_asia',-403,1,NULL,'year',-230,12,NULL,'month',-4824,-2737,'ochre',NULL,NULL,'三家分晋后韩氏立国，前403年周天子册命；前230年秦灭韩。');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-fei','韩非','han-warring','[]',NULL,NULL,-280,1,NULL,'year',-233,1,NULL,'year','["思想家"]','法家集大成者，秦王政重其书，后遭李斯害死；代表作有《孤愤》《五蠹》，主张法、术、势并用；入秦后遭李斯构陷，在狱中自尽。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩非"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-jing','虔','han-warring','["韩景侯"]','姬','韩',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','韩武子之子，继掌晋国韩氏。韩氏此前与赵、魏于前453年灭智氏并分取其地，形成独立军政势力；景侯继续与魏、赵合作，前403年三家同受周天子册封，韩正式成为诸侯。其时与郑争夺阳翟等地，尚未迁都新郑。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩景侯"}]','景',NULL,'景侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-r1','取','han-warring','["韩烈侯"]','姬','韩',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','景侯之子，烈侯。在位十二年，韩国初立，实力一般，无力争霸，国势平稳，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩烈侯"}]','烈',NULL,'烈侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-r10','安','han-warring','[]','姬','韩',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','韩国末代君主。前230年秦灭韩，国亡，韩国历史终结，姬姓韩国不复存在，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/安"}]',NULL,NULL,'安','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-r2','猷','han-warring','["韩文侯"]','姬','韩',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','文侯，在位九年。韩国继续发展，未成大患，国势平稳，无力争霸，事迹载于《史记》相关记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩文侯"}]','文',NULL,'文侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-r3','屯蒙','han-warring','["韩哀侯"]','姬','韩',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','哀侯，在位仅三年。韩国实力尚弱，无力外争，维持小国局面，国势平平，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩哀侯"}]','哀',NULL,'哀侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-r4','若山','han-warring','["韩共侯"]','姬','韩',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','共侯，曾与赵攻魏，于浊泽大胜。因与赵争利未灭魏，魏得以存续，韩国错失良机，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩共侯"}]','共',NULL,'共侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-r5','武','han-warring','["韩釐侯"]','姬','韩',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','即韩昭侯，任申不害变法，以术治国。韩国国力达于最强，诸侯不敢侵伐，为韩国巅峰，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩釐侯"}]','釐',NULL,'釐侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-r6','康','han-warring','["韩宣惠王"]','姬','韩',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','昭侯之子，宣惠王。在位时韩国称王，参与合纵连横，国势尚可，无力争霸，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩宣惠王"},{"label":"《史记·韩世家》","url":"https://zh.wikisource.org/zh-hans/史記/卷045"},{"label":"《资治通鉴》卷2","url":"https://zh.wikisource.org/zh-hans/資治通鑑/卷002"}]','宣惠',NULL,'宣惠王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-r7','仓','han-warring','["韩襄王"]','姬','韩',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','襄王，在位十五年。与诸侯周旋，韩国已渐弱，无力争霸，国势转衰，事迹载于《史记》相关记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩襄王"}]','襄',NULL,'襄王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-r8','咎','han-warring','["韩釐王"]','姬','韩',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','在位二十三年，秦国东进，韩国屡遭攻伐，割地求和，国势危急，濒临灭亡，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩釐王"}]','釐',NULL,'釐王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('han-r9','然','han-warring','["韩桓惠王"]','姬','韩',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','桓惠王，在位三十三年。韩国沦为秦国附庸，割地求和，国势危急，濒临灭亡，事迹见《史记》。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/韩桓惠王"}]','桓惠',NULL,'桓惠王','[]');
