INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('han-xuanhui-assumes-kingship','韩宣惠君称王','politics','point','year',NULL,NULL,'采用前323年系年；五国相王的参与及赵是否实际称王应区分，不能将赵武灵王拒绝王号改写为同年正式称王。',-323,12,NULL,-3853,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'-323年，韩宣惠君采用王号，韩国由侯称转入称王阶段。秦、齐、魏已经采用王号，列国又通过外交活动互认名号，韩借此争取与强国对等的身份。同年燕也称王，赵武灵王却以实力不足拒绝采用王称；这说明称王取决于各国的政治选择，并非周王统一升爵。',NULL,NULL,'[{"label":"《史记·韩世家》","url":"https://zh.wikisource.org/zh-hans/史記/卷045"},{"label":"《资治通鉴》卷2","url":"https://zh.wikisource.org/zh-hans/資治通鑑/卷002"}]');
